class DailyShloka {
  final int id;
  final String sanskrit;
  final String hindi;
  final String source;
  const DailyShloka({
    required this.id,
    required this.sanskrit,
    required this.hindi,
    required this.source,
  });
}

/// Port of shakti_panchang `src/constants/shlokas.ts`.
class DailyShlokaData {
  static DailyShloka forDate(DateTime date) {
    final i = DateTime(date.year, date.month, date.day).difference(DateTime(2020, 1, 1)).inDays;
    return shlokas[i.abs() % shlokas.length];
  }

  static const List<DailyShloka> shlokas = [
    DailyShloka(id: 1, sanskrit: 'कर्मण्येवाधिकारस्ते मा फलेषु कदाचन।\nमा कर्मफलहेतुर्भूर्मा ते सङ्गोऽस्त्वकर्मणि॥', hindi: 'तुम्हारा अधिकार केवल कर्म करने में है, उसके फलों में कभी नहीं।', source: 'श्रीमद्भगवद्गीता (२.४७)'),
    DailyShloka(id: 2, sanskrit: 'उद्यमेन हि सिध्यन्ति कार्याणि न मनोरथैः।\nन हि सुप्तस्य सिंहस्य प्रविशन्ति मुखे मृगाः॥', hindi: 'कार्य परिश्रम से सिद्ध होते हैं, केवल इच्छा से नहीं।', source: 'हितोपदेशः'),
    DailyShloka(id: 3, sanskrit: 'यदा यदा हि धर्मस्य ग्लानिर्भवति भारत।\nअभ्युत्थानमधर्मस्य तदात्मानं सृजाम्यहम्॥', hindi: 'जब-जब धर्म की हानि होती है, तब मैं प्रकट होता हूँ।', source: 'श्रीमद्भगवद्गीता (४.७)'),
    DailyShloka(id: 4, sanskrit: 'विद्या ददाति विनयं विनयाद्याति पात्रताम्।\nपात्रत्वाद्धनमाप्नोति धनाद्धर्मं ततः सुखम्॥', hindi: 'विद्या विनय देती है, विनय से योग्यता, फिर धर्म और सुख।', source: 'हितोपदेशः'),
    DailyShloka(id: 5, sanskrit: 'अयं निजः परो वेति गणना लघुचेतसाम्।\nउदारचरितानां तु वसुधैव कुटुम्बकम्॥', hindi: 'उदार लोगों के लिए पूरी पृथ्वी एक परिवार है।', source: 'महोपनिषद् (४.७१)'),
    DailyShloka(id: 6, sanskrit: 'सर्वे भवन्तु सुखिनः सर्वे सन्तु निरामयाः।\nसर्वे भद्राणि पश्यन्तु मा कश्चिद्दुःखभाग्भवेत्॥', hindi: 'सभी सुखी हों, सभी निरोग रहें, कोई दुःखी न हो।', source: 'बृहदारण्यकोपनिषद्'),
    DailyShloka(id: 7, sanskrit: 'सत्यं ब्रूयात् प्रियं ब्रूयात् न ब्रूयात् सत्यमप्रियम्।\nप्रियं च नानृतं ब्रूयात् एष धर्मः सनातनः॥', hindi: 'सत्य और प्रिय बोलो; अप्रिय सत्य या प्रिय असत्य नहीं।', source: 'मनुस्मृतिः (४.१३८)'),
    DailyShloka(id: 8, sanskrit: 'आलस्यं हि मनुष्याणां शरीरस्थो महान् रिपुः।\nनास्त्युद्यमसमो बन्धुः कृत्वा यं नावसीदति॥', hindi: 'आलस्य सबसे बड़ा शत्रु है, उद्यम सबसे बड़ा मित्र।', source: 'भर्तृहरि नीतिशतकम्'),
    DailyShloka(id: 9, sanskrit: 'अभिवादनशीलस्य नित्यं वृद्धोपसेविनः।\nचत्वारि तस्य वर्धन्ते आयुर्विद्या यशो बलम्॥', hindi: 'बड़ों के सम्मान से आयु, विद्या, यश और बल बढ़ते हैं।', source: 'मनुस्मृतिः (२.१२१)'),
    DailyShloka(id: 10, sanskrit: 'माता शत्रुः पिता वैरी येन बालो न पाठितः।\nन शोभते सभामध्ये हंसमध्ये बको यथा॥', hindi: 'बिना विद्या के बालक सभा में शोभा नहीं पाता।', source: 'चाणक्य नीतिः'),
    DailyShloka(id: 11, sanskrit: 'सुखार्थिनः कुतो विद्या नास्ति विद्यार्थिनः सुखम्।\nसुखार्थी वा त्यजेद्विद्यां विद्यार्थी वा त्यजेत्सुखम्॥', hindi: 'विद्या और सुख-आलस्य साथ नहीं रहते।', source: 'चाणक्य नीतिः'),
    DailyShloka(id: 12, sanskrit: 'धृतिः क्षमा दमोऽस्तेयं शौचमिन्द्रियनिग्रहः।\nधीर्विद्या सत्यमक्रोधो दशकं धर्मलक्षणम्॥', hindi: 'धैर्य, क्षमा, संयम, सत्य — धर्म के दस लक्षण।', source: 'मनुस्मृतिः (६.९२)'),
    DailyShloka(id: 13, sanskrit: 'काव्यशास्त्रविनोदेन कालो गच्छति धीमताम्।\nव्यसनेन तु मूर्खाणां निद्रया कलहेन वा॥', hindi: 'ज्ञानी का समय शास्त्र में जाता है, मूर्ख का कलह में।', source: 'हितोपदेशः'),
    DailyShloka(id: 14, sanskrit: 'नास्ति विद्यासमं चक्षुर्नास्ति सत्यसमं तपः।\nनास्ति रागसमं दुःखं नास्ति त्यागसमं सुखम्॥', hindi: 'विद्या नेत्र है, सत्य तप है, त्याग ही सुख है।', source: 'महाभारतम्'),
    DailyShloka(id: 15, sanskrit: 'यत्र नार्यस्तु पूज्यन्ते रमन्ते तत्र देवताः।\nयत्रैतास्तु न पूज्यन्ते सर्वास्तत्राफलाः क्रियाः॥', hindi: 'जहाँ नारी पूजित हैं वहाँ देवता बसते हैं।', source: 'मनुस्मृतिः (३.५६)'),
    DailyShloka(id: 16, sanskrit: 'यस्य नास्ति स्वयं प्रज्ञा शास्त्रं तस्य करोति किम्।\nलोचनाभ्यां विहीनस्य दर्पणः किं करिष्यति॥', hindi: 'बिना विवेक के शास्त्र दर्पण के समान व्यर्थ।', source: 'चाणक्य नीतिः'),
    DailyShloka(id: 17, sanskrit: 'परोपकाराय फलन्ति वृक्षाः परोपकाराय वहन्ति नद्यः।\nपरोपकाराय दुहन्ति गावः परोपकारार्थमिदं शरीरम्॥', hindi: 'यह शरीर परोपकार के लिए है।', source: 'सुभाषितरत्नभाण्डागारम्'),
    DailyShloka(id: 18, sanskrit: 'असतो मा सद्गमय तमसो मा ज्योतिर्गमय।\nमृत्योर्मा अमृतं गमय ओं शान्तिः शान्तिः शान्तिः॥', hindi: 'असत्य से सत्य, अंधकार से प्रकाश, मृत्यु से अमरता की ओर ले चलो।', source: 'बृहदारण्यकोपनिषद् (१.३.२८)'),
    DailyShloka(id: 19, sanskrit: 'दुर्जनः परिहर्तव्यो विद्ययालङ्कृतोऽपि सन्।\nमणिना भूषितः सर्पः किमसौ न भयङ्करः॥', hindi: 'विद्या से अलंकृत दुर्जन भी त्याज्य है।', source: 'भर्तृहरि नीतिशतकम्'),
    DailyShloka(id: 20, sanskrit: 'हस्तस्य भूषणं दानं सत्यं कण्ठस्य भूषणम्।\nश्रोत्रस्य भूषणं शास्त्रं भूषणैः किं प्रयोजनम्॥', hindi: 'दान, सत्य और शास्त्र ही सच्चे आभूषण हैं।', source: 'सुभाषितसुधानिधिः'),
    DailyShloka(id: 21, sanskrit: 'अनित्यानि शरीराणि विभवो नैव शाश्वतः।\nनित्यं सन्निहितो मृत्युः कर्तव्यो धर्मसङ्ग्रहः॥', hindi: 'शरीर नश्वर है — धर्म का संचय करो।', source: 'कथासरित्सागरः'),
    DailyShloka(id: 22, sanskrit: 'न कश्चित् कस्यचिन्मित्रं न कश्चित् कस्यचिद्रिपुः।\nव्यवहारेण जायन्ते मित्राणि रिपवस्तथा॥', hindi: 'मित्र-शत्रु व्यवहार से बनते हैं, जन्म से नहीं।', source: 'विदुर नीतिः'),
    DailyShloka(id: 23, sanskrit: 'यथा चित्तं तथा वाचो यथा वाचस्तथा क्रियाः।\nचित्ते वाचि क्रियायां च साधूनामेकरूपता॥', hindi: 'सज्जन के मन, वचन और कर्म एक हैं।', source: 'हितोपदेशः'),
    DailyShloka(id: 24, sanskrit: 'सम्पत्तौ च विपत्तौ च महतामेकरूपता।\nउदये सविता रक्तो रक्तश्चास्तमये तथा॥', hindi: 'महापुरुष सुख-दुःख में सूर्य की तरह सम रहते हैं।', source: 'सुभाषितरत्नभाण्डागारम्'),
    DailyShloka(id: 25, sanskrit: 'ओं त्र्यम्बकं यजामहे सुगन्धिं पुष्टिवर्धनम्।\nउर्वारुकमिव बन्धनान्मृत्योर्मुक्षीय माऽमृतात्॥', hindi: 'त्र्यम्बक से पुष्टि और मृत्यु-बंधन से मुक्ति की प्रार्थना।', source: 'ऋग्वेद महामृत्युंजय'),
  ];
}
